export function spacecraftMaterialRecord(h){
 const identity=designIdentity(h),assignments=spacecraftSurfaceAssignments(h),used=new Set(assignments.map(x=>x.materialId)),sourceIds=new Set(assignments.flatMap(x=>x.evidence.sourceIds));
 return {schema:'orbital-data-center/materials/1',revision:materialLibraryRevision,architectureFamily:architectureFamily(h).id,referenceId:h.input?.referenceCenterId||null,referenceRevision:h.input?.referenceCenterRevision||null,reference:identity.reference,physicalArchitectureId:h.physicalArchitecture?.physicalId||identity.vehicleId,identity:{vehicleId:identity.vehicleId,missionId:identity.missionId,analysisId:identity.analysisId},policy:{scope:'PDR visible-material and finish allocations with selective concealed layers. No fastener-level BOM.',mass:'All surface details are non-additive and accounted for by their parent MEL items.',evidence:'Generic material heritage does not establish the reference provider’s selection.',visuals:visualBoundary,physics:'Rendering values never replace the existing thermal optical coefficients, mass allocations, conductivity or structural allowables.'},modelProperties:{solarTechnology:h.input?.pv,radiatorFinish:h.input?.coating,radiatorAbsorptivity:h.input?.absorptivity,radiatorEmissivity:h.input?.emissivity,blanketEffectiveEmissivity:h.input?.blanketEffectiveEpsilon,blanketOuterEmissivity:h.input?.blanketOuterEpsilon,blanketOuterAbsorptivity:h.input?.blanketOuterAlpha,verification:'These are study model inputs. No per-zone amber/white blanket optical weighting or material qualification has been established.'},materials:[...used].map(id=>spacecraftMaterials[id]),assignments,sources:[...sourceIds].map(id=>materialSources[id]).filter(Boolean)};
}
